  "ph.sd": "စံသွေဖည်ချက်",
  "L.an_overview.title": "A1 ဒေတာ၏ ခြုံငုံပုံကို ကြည့်ပါ",
  "L.an_overview.point": "ခွဲခြမ်းစိတ်ဖြာမီ အရွယ်အစားနှင့် အပိုင်းအခြားကို စစ်ပါ- တန်းအရေအတွက်၊ အငယ်ဆုံးနှင့် အကြီးဆုံးတန်ဖိုး၊ ပထမနှင့် နောက်ဆုံးရက်စွဲ။ ထူးဆန်းသောတန်ဖိုးများ ဤနေရာတွင် မကြာခဏ တွေ့ရသည်။",
  "L.an_overview.desc": "{t} ဇယား၏ တန်းအရေအတွက်၊ အငယ်ဆုံးနှင့် အကြီးဆုံး {v}၊ ပထမနှင့် နောက်ဆုံး {dt} ကို တန်းတစ်တန်းတည်းတွင် ထုတ်ပါ။",
  "L.an_missing.title": "A2 ပျောက်နေသောတန်ဖိုးနှင့် ထပ်နေသောတန်ဖိုး",
  "L.an_missing.point": "COUNT(*) သည် တန်းများကို ရေတွက်သည်။ COUNT(ကော်လံ) သည် ဖြည့်ထားသောတန်ဖိုးများကိုသာ ရေတွက်သည်။ ခြားနားချက်သည် ပျောက်နေသောတန်ဖိုး (NULL) အရေအတွက်ဖြစ်သည်။ COUNT(DISTINCT ကော်လံ) သည် တန်ဖိုးတစ်ခုစီကို တစ်ကြိမ်သာ ရေတွက်သည်။",
  "L.an_missing.desc": "{t} ဇယားတွင် ပျောက်နေသောတန်ဖိုးနှင့် ထပ်နေသောတန်ဖိုးများကို စစ်ပါ။",
  "L.an_missing.desc_null": "{t} ဇယားတွင် {opt} မရှိသော (NULL) တန်း ဘယ်နှတန်းရှိသနည်း။ တန်းအရေအတွက်၊ ဖြည့်ထားသောတန်ဖိုး၊ ပျောက်နေသောတန်ဖိုး နှင့် ပျောက်နေသည့် ရာခိုင်နှုန်း (%၊ ဒသမ ၁ နေရာ) ကို ထုတ်ပါ။",
  "L.an_missing.desc_dup": "{t} ဇယားတွင် မတူညီသော {name} ဘယ်နှခုရှိသနည်း။ တန်းအရေအတွက်နှင့် မထပ်သော {name} အရေအတွက်ကို ထုတ်ပါ။",
  "L.an_center.title": "A3 ပျမ်းမျှ၊ အလယ်ကိန်းနှင့် အများဆုံးကိန်း",
  "L.an_center.point": "အလွန်ကြီးသောတန်ဖိုးများက ပျမ်းမျှကို ဆွဲယူသည်။ အလယ်ကိန်း (အလယ်တန်ဖိုး) ကို မဆွဲပါ။ နှစ်ခု အလွန်ကွာနေလျှင် ဒေတာသည် တစ်ဘက်သို့ စောင်းနေသည်။ အများဆုံးကိန်းသည် အများဆုံးပေါ်သော တန်ဖိုးဖြစ်သည်။",
  "L.an_center.desc": "{t} ၏ ဗဟိုကို ရှာပါ။",
  "L.an_center.desc_mid": "{t} ဇယားရှိ {v} ၏ ပျမ်းမျှ (ဒသမ ၁ နေရာ) နှင့် အလယ်ကိန်းကို ထုတ်ပါ။ ဇယားတွင် {n} တန်းရှိသောကြောင့် အလယ်ကိန်းသည် အငယ်ဆုံးမှ {pos} ခုမြောက်တန်ဖိုး ဖြစ်သည် ({k} တန်း ကျော်ပါ)။",
  "L.an_center.desc_mode": "{t} ဇယားတွင် {v2} ၏ မည်သည့်တန်ဖိုး အများဆုံး ပေါ်သနည်း (အများဆုံးကိန်း)။ ထိုတန်ဖိုးနှင့် ၎င်း၏ တန်းအရေအတွက်ကို ထုတ်ပါ။",
  "L.an_spread.title": "A4 ပျံ့နှံ့မှု- အပိုင်းအခြားနှင့် စံသွေဖည်ချက်",
