  "L.an_spread.desc": "{t} ရှိ အုပ်စုတစ်ခုစီ၏ ပျံ့နှံ့မှုကို နှိုင်းယှဉ်ပါ။",
  "L.an_spread.desc_sd": "{t} ဇယားရှိ {g} တစ်ခုစီအတွက် တန်းအရေအတွက်၊ {v} ၏ ပျမ်းမျှနှင့် စံသွေဖည်ချက် (နှစ်ခုလုံး ဒသမ ၁ နေရာ) ကို စံသွေဖည်ချက် အငယ်ဆုံးမှစ၍ ထုတ်ပါ။",
  "L.an_spread.desc_range": "{t} ဇယားရှိ {g} တစ်ခုစီအတွက် အငယ်ဆုံးနှင့် အကြီးဆုံး {v} နှင့် အပိုင်းအခြား (အကြီးဆုံး − အငယ်ဆုံး) ကို အပိုင်းအခြား အငယ်ဆုံးမှစ၍ ထုတ်ပါ။",
  "L.an_hist.title": "A5 ဖြန့်ဝေမှု- ကြိမ်နှုန်းဇယားနှင့် ဟစ်စတိုဂရမ်",
  "L.an_hist.point": "တန်ဖိုးများကို အကျယ်တူ အတန်းများအဖြစ် ခွဲပြီး အတန်းတစ်ခုစီရှိ တန်းများကို ရေတွက်ပါ။ ဟစ်စတိုဂရမ်သည် ပုံသဏ္ဌာန်ကို ပြသည်- တန်ဖိုးအများစု ဘယ်မှာရှိသလဲ၊ တစ်ဘက်တွင် အမြီးရှည် ရှိမရှိ။",
  "L.an_hist.desc": "{t} ၏ ကြိမ်နှုန်းဇယားကို ပြုလုပ်ပါ။",
  "L.an_hist.desc_bin": "{t} ဇယားရှိ {v} ၏ ကြိမ်နှုန်းဇယားကို {step} အကျယ်ရှိ အတန်းများဖြင့် ပြုလုပ်ပါ- အတန်းတစ်ခုစီ၏ အစတန်ဖိုးနှင့် တန်းအရေအတွက်ကို အစဉ်လိုက် ထုတ်ပါ။",
  "L.an_hist.desc_freq": "{t} ဇယားရှိ {v2} ၏ တန်ဖိုးတစ်ခုစီအတွက် တန်းအရေအတွက်နှင့် တန်းအားလုံးတွင် ၎င်း၏ ရာခိုင်နှုန်း (%၊ ဒသမ ၁ နေရာ) ကို {v2} အစဉ်အတိုင်း ထုတ်ပါ။",
  "L.an_zscore.title": "A6 စံရမှတ် (z) နှင့် ထူးခြားသောတန်ဖိုး",
