  "L.an_zscore.desc_top": "{t} ဇယားတွင် {v} ၏ ပျမ်းမျှသည် {m} ဖြစ်ပြီး စံသွေဖည်ချက်သည် {s} ဖြစ်သည်။ z ရမှတ် အကြီးဆုံး ၅ တန်း၏ {id}၊ {v} နှင့် z ရမှတ် (ဒသမ ၂ နေရာ) ကို ထုတ်ပါ။",
  "L.an_zscore.desc_count": "{t} ဇယားတွင် {v} ၏ ပျမ်းမျှသည် {m} ဖြစ်ပြီး စံသွေဖည်ချက်သည် {s} ဖြစ်သည်။ ပျမ်းမျှမှ စံသွေဖည်ချက် ၂ ခုနှင့်အထက် ကွာသော (|z| ≥ 2) တန်း ဘယ်နှတန်း ရှိသနည်း။",
