  "L.an_cross.title": "A7 Cross ဇယားနှင့် အချိုး",
  "L.an_cross.point": "အုပ်စုများကို နှိုင်းယှဉ်ရန် ကော်လံနှစ်ခုဖြင့် တစ်ပြိုင်နက် ရေတွက်ပါ။ အချိုး (%) ဖြင့် အရွယ်အစားမတူသော အုပ်စုများကို နှိုင်းယှဉ်နိုင်သည်။ SUM(CASE WHEN … THEN 1 ELSE 0 END) သည် အခြေအနေနှင့် ကိုက်ညီသော တန်းများကိုသာ ရေတွက်ပြီး တန်ဖိုးတစ်ခုစီကို ကိုယ်ပိုင်ကော်လံတွင် ထားသည်။",
