  "L.an_cross.desc_pivot": "{t} ဇယားတွင် {g} တစ်ခုစီအတွက် {opt} သည် {a1} ဖြစ်သော တန်းနှင့် {a2} ဖြစ်သော တန်းများ (တစ်ခုစီ ကော်လံတစ်ခု) နှင့် တန်းအားလုံး အရေအတွက်ကို ရေတွက်ပါ။ {g} အလိုက် စီပါ။",
