  "L.an_read.c_same": "နှစ်ခုစလုံး အတူတူနီးပါး ဖြစ်သောကြောင့် မည်သည့်တစ်ခုမဆို ရသည်",
  "L.an_read.c_strong": "ပြင်းထန် (|r| ≥ 0.7)",
  "L.an_read.c_moderate": "အလယ်အလတ် (0.4 ≤ |r| < 0.7)",
  "L.an_read.c_weak": "အားနည်း (0.2 ≤ |r| < 0.4)",
  "L.an_read.c_none": "မရှိသလောက် (|r| < 0.2)",
  "L.an_read.c_tend": "{v} နှင့် {v3} အတူ ပြောင်းလဲသည် (ဆက်နွယ်မှုရှိသည်)၊ သို့သော် တစ်ခုက အခြားတစ်ခုကို ဖြစ်စေသည်ဟု မပြပါ",
  "L.an_read.c_cause": "{v3} ကို ပြောင်းလျှင် {v} ပြောင်းမည် (တစ်ခုသည် အခြားတစ်ခု၏ အကြောင်းရင်း)",
  "L.an_read.c_noRel": "{v} နှင့် {v3} တွင် ဆက်နွယ်မှု မရှိပါ",
  "L.an_read.why_center": "အလွန်ကြီးသော တန်ဖိုးအနည်းငယ်က ပျမ်းမျှကို အပေါ်ဆွဲတင်သောအခါ အလယ်ကိန်းက ပုံမှန်တန်ဖိုးကို ပိုကောင်းစွာ ပြသည်။ နှစ်ခု နီးနေလျှင် ဒေတာ မစောင်းသောကြောင့် ပျမ်းမျှ သုံးလည်း ရသည်။",
  "L.an_read.why_corr": "r ၏ အရွယ်အစားကို ကြည့်ပါ- 0.7 နှင့်အထက် ပြင်းထန်၊ 0.4–0.7 အလယ်အလတ်၊ 0.2–0.4 အားနည်း၊ 0.2 အောက် မရှိသလောက်။",
  "L.an_read.why_cause": "ဆက်နွယ်မှုသည် နှစ်ခု အတူပြောင်းလဲသည်ဟုသာ ဆိုသည်။ တတိယအရာတစ်ခုက နှစ်ခုလုံးကို ပြောင်းစေနိုင်သည်၊ သို့မဟုတ် ဦးတည်ချက် ပြောင်းပြန် ဖြစ်နိုင်သည်။ အကြောင်းရင်းကို ပြရန် စမ်းသပ်မှု သို့မဟုတ် အထောက်အထား ထပ်လိုသည်။",
  "L.an_read.why_share": "တန်းအများဆုံး အုပ်စုသည် အချိုးအကြီးဆုံး အုပ်စု အမြဲ မဟုတ်ပါ။ အုပ်စုကြီးများတွင် အရာအားလုံး ပိုများသည်- % ကို နှိုင်းယှဉ်ပါ။",
  "L.an_read.why_trend": "စုစုပေါင်း အကြီးဆုံးလသည် အများဆုံးတိုးသောလ မဟုတ်ပါ။ diff ကော်လံကို ဖတ်ပါ။",
  "L.an_read.why_outlier": "z ၃ နှင့်အထက်ရှိသော တန်းများကို ရေတွက်ပါ။ z ၂ နှင့် ၃ ကြား တန်ဖိုးများကို ကြည့်သင့်သော်လည်း ဤစည်းမျဉ်းအရ ထူးခြားသောတန်ဖိုး မဟုတ်ပါ။",
  "L.an_case.title": "A14 ပရောဂျက်- နောက်ကမ်ပိန်းကို ဘယ်မှာလုပ်မလဲ",
  "L.an_case.point": "Kumo Mart သည် ဆိုင်တစ်ဆိုင်တွင် ကူပွန်ဝေမည်။ သင်ယူခဲ့သည်များကို တစ်ဆင့်ချင်း သုံးပါ- ခြုံငုံပုံ၊ အချိုး၊ အချိန်အလိုက် နှိုင်းယှဉ်ချက်၊ ကူပွန်ပါ/မပါ နှင့် ဖောက်သည်များ။ ထို့နောက် ကိန်းဂဏန်းများကို အကြောင်းပြချက်အဖြစ် သုံး၍ ဆုံးဖြတ်ပါ။",
  "L.an_case.desc": "Kumo Mart ၏ နောက်ကမ်ပိန်း။",
  "L.an_case.desc_overview": "အဆင့် ၁ — ခြုံငုံပုံ။ kumo_orders မှ ဆိုင်တစ်ဆိုင်စီအတွက် အော်ဒါအရေအတွက်၊ စုစုပေါင်းငွေ (total_amount) နှင့် ပျမ်းမျှငွေ (ဒသမ ၁ နေရာ) ကို စုစုပေါင်း အကြီးဆုံးမှစ၍ ထုတ်ပါ။",
  "L.an_case.desc_coupon": "အဆင့် ၂ — ယခု ကူပွန်ကို ဘယ်လောက် သုံးနေသလဲ။ ဆိုင်တစ်ဆိုင်စီအတွက် အော်ဒါအရေအတွက်နှင့် ကူပွန်ပါ အော်ဒါ၏ ရာခိုင်နှုန်း (pct_coupon၊ %၊ ဒသမ ၁ နေရာ) ကို ရာခိုင်နှုန်း အငယ်ဆုံးမှစ၍ ထုတ်ပါ။",
  "L.an_case.desc_half": "အဆင့် ၃ — ဆိုင် တိုးတက်နေသလား။ ဆိုင်တစ်ဆိုင်စီအတွက် 2025-07-01 မတိုင်မီ စုစုပေါင်းငွေ (first_half) နှင့် 2025-07-01 မှစ၍ စုစုပေါင်းငွေ (second_half) ကို ဆိုင်အစဉ်အတိုင်း ထုတ်ပါ။",
  "L.an_case.desc_effect": "အဆင့် ၄ — ကူပွန်ပါ အော်ဒါများ ပိုကြီးသလား။ ဆိုင်တစ်ဆိုင်စီအတွက် ကူပွန်ပါ (with_coupon) နှင့် မပါ (without_coupon) အော်ဒါ၏ ပျမ်းမျှငွေကို ဒသမ ၁ နေရာဖြင့် ဆိုင်အစဉ်အတိုင်း ထုတ်ပါ။",
  "L.an_case.desc_members": "အဆင့် ၅ — ဖောက်သည်များ ဘယ်သူတွေလဲ။ customer_id ဖြင့် kumo_orders နှင့် kumo_accounts ကို ချိတ်ပါ။ ဆိုင်တစ်ဆိုင်စီအတွက် အော်ဒါအရေအတွက်နှင့် Regular အစီအစဉ် ဖောက်သည်များ၏ အော်ဒါ ရာခိုင်နှုန်း (pct_regular၊ ဒသမ ၁ နေရာ) ကို ရာခိုင်နှုန်း အကြီးဆုံးမှစ၍ ထုတ်ပါ။",
  "L.an_case.desc_decide": "အဆင့် ၆ — ဆုံးဖြတ်ပါ။ စိတ်ကူး- တိုးတက်နေသော ဆိုင်များထဲတွင် ကူပွန် အနည်းဆုံးသုံးသော နေရာ၌ ကူပွန်ပေးခြင်း။ ဒုတိယနှစ်ဝက်တွင် ရောင်းအား တိုးသော (growth > 0) ဆိုင်များထဲမှ မည်သည့်ဆိုင်တွင် ကူပွန် ရာခိုင်နှုန်း အနိမ့်ဆုံး ဖြစ်သနည်း။",
  "L.an_case.why_decide": "growth 0 ထက်ကြီးသော ဆိုင်များကို ရှာပြီး ၎င်းတို့ထဲမှ pct_coupon အငယ်ဆုံးကို ရှာပါ။ ကောင်းသော အစီရင်ခံစာသည် ကိန်းဂဏန်းဖြင့် အကြောင်းပြချက်ကို ပြောသည်- “{ans} တွင် ရောင်းအား တိုးနေသော်လည်း ကူပွန်သုံးသော အော်ဒါ နည်းပါးသည်။”",
