  "pd.p.pd_head": "ဇယား (DataFrame) ၏ ပထမအတန်းအချို့ကို `ဇယား.head(n)` ဖြင့် ကြည့်နိုင်သည်။ SQL ၏ `LIMIT` နှင့် တူသည်။",
  "pd.p.pd_cols": "ကော်လံရွေးရန် ကော်လံအမည်စာရင်းကို [ ] အတွင်း ထည့်ပါ: `ဇယား[[\"ကော်လံ1\", \"ကော်လံ2\"]]`။ [ ] နှစ်ထပ်ကို သတိပြုပါ။ SQL ၏ `SELECT ကော်လံ1, ကော်လံ2` နှင့် တူသည်။",
  "pd.p.pd_num": "`ဇယား[ဇယား[\"ကော်လံ\"] >= တန်ဖိုး]` သည် အခြေအနေနှင့် ကိုက်ညီသော အတန်းများကိုသာ ထားသည်။ အတွင်းပိုင်းက အတန်းတိုင်းအတွက် True / False ပြုလုပ်ပြီး အပြင် [ ] က True အတန်းများကို ထားသည်။ SQL ၏ `WHERE` နှင့် တူသည်။",
  "pd.p.pd_text": "စာတန်ဖိုးကို \" \" အတွင်း ရေးပါ: `ဇယား[ဇယား[\"ကော်လံ\"] == \"တန်ဖိုး\"]`။ ညီသည် `==` (= နှစ်ခု)၊ မညီ `!=`။",
  "pd.p.pd_andor": "အခြေအနေများ ပေါင်းရန် တစ်ခုစီကို ( ) ဖြင့် ပိတ်ပြီး `&` (နှင့်) သို့မဟုတ် `|` (သို့မဟုတ်) ဖြင့် ဆက်ပါ: `ဇယား[(အခြေ1) & (အခြေ2)]`။ and / or စကားလုံး မဟုတ်ပါ။",
  "pd.p.pd_loc": "`ဇယား.loc[အခြေအနေ, [\"ကော်လံ1\", \"ကော်လံ2\"]]` သည် အတန်းစစ်ရင်း ကော်လံလည်း ရွေးသည်။ `ဇယား[အခြေအနေ][[\"ကော်လံ1\", \"ကော်လံ2\"]]` လည်း ရလဒ်တူသည်။",
  "pd.p.pd_sort": "`ဇယား.sort_values(\"ကော်လံ\")` သည် ငယ်မှကြီး စီသည်။ `ascending=False` ထည့်လျှင် ကြီးမှငယ်။ SQL ၏ `ORDER BY` နှင့် တူသည်။",
  "pd.p.pd_top": "စီပြီးနောက် `.head(n)` ဆက်လျှင် ထိပ်ဆုံးအတန်းများ ရသည်: `ဇယား.sort_values(\"ကော်လံ\", ascending=False).head(3)`။",
  "pd.p.pd_agg": "`ဇယား[\"ကော်လံ\"].mean()` ပျမ်းမျှ၊ `.sum()` စုစုပေါင်း၊ `.max()` အကြီးဆုံး၊ `.min()` အငယ်ဆုံး။ အဖြေသည် တန်ဖိုးတစ်ခု ဖြစ်သည်။",
  "pd.p.pd_group": "`ဇယား.groupby(\"အုပ်စုကော်လံ\")[\"ကော်လံ\"].mean()` သည် အုပ်စုတစ်ခုစီကို တွက်သည်။ SQL ၏ `GROUP BY` နှင့် တူသည်။",
  "pd.p.pd_count": "`ဇယား[\"ကော်လံ\"].value_counts()` သည် တန်ဖိုးတစ်ခုစီ၏ အတန်းအရေအတွက်ကို ရေတွက်သည်။ SQL ၏ `GROUP BY ကော်လံ` နှင့် `COUNT(*)` နှင့် တူသည်။",
  "pd.p.pd_merge": "`pd.merge(ဇယား1, ဇယား2, left_on=\"ကော်လံ1\", right_on=\"ကော်လံ2\")` သည် တန်ဖိုးတူသော အတန်းများကို ချိတ်ဆက်သည်။ SQL ၏ `INNER JOIN … ON` နှင့် တူသည်။",
  "pd.d.head": "{t} ၏ ပထမ {n} တန်းကို ပြပါ။",
