  "L.calc.desc_tax": "{t} ဇယားမှ {name}၊ {c} နှင့် အခွန် {pct}% ပါဝင်သော {c} (ကိန်းပြည့်သို့ အနီးစပ်ဆုံး) ကို ထုတ်ပါ။",
  "L.calc.desc_ratio": "{t} ဇယားမှ {name} နှင့် {c} ကို {c2} ဖြင့်စားထားသော တန်ဖိုး (ဒသမ {d} နေရာအထိ) ကို ထုတ်ပါ။",
  "L.calc.desc_avg": "{t} ဇယား၏ {cat} တစ်ခုစီအတွက် {cat} နှင့် {c} ၏ ပျမ်းမျှ (ဒသမ {d} နေရာအထိ) ကို ထုတ်ပါ။",
  "L.coalesce.title": "NULL အစားထိုးခြင်း (COALESCE)",
