  "L.coalesce.desc": "{t} ဇယားမှ {name} နှင့် {opt} ကို ထုတ်ပါ၊ သို့သော် {opt} NULL ဖြစ်လျှင် {fill} ဟု ပြပါ။",
  "L.coalesce.desc_fill": "{t} ဇယားမှ {name} နှင့် {opt} ကို ထုတ်ပါ၊ သို့သော် {opt} NULL ဖြစ်လျှင် {fill} ဟု ပြပါ။",
  "L.coalesce.desc_count": "{t} ဇယား၏ {cat} တစ်ခုစီအတွက် {cat}၊ အတန်းအားလုံးအရေအတွက်နှင့် {opt} ဖြည့်ထားသော (NULL မဟုတ်သော) အတန်းအရေအတွက်ကို ထုတ်ပါ။",
  "L.strfn.title": "စာသား function များ (UPPER, LENGTH, SUBSTR, ||)",
  "L.strfn.point": "UPPER သည် စာလုံးကြီးပြောင်းသည်၊ LENGTH သည် စာလုံးရေတွက်သည်၊ SUBSTR(စာသား, စမှတ်, အရှည်) သည် အပိုင်းတစ်ခုကို ဖြတ်ယူသည်၊ || သည် စာသားဆက်သည်။",
  "L.strfn.desc": "{t} ဇယားမှ {name} ကို စာလုံးကြီးအားလုံးဖြင့် ထုတ်ပါ။",
  "L.strfn.desc_upper": "{t} ဇယားမှ {name} ကို စာလုံးကြီးအားလုံးဖြင့် ထုတ်ပါ။",
