  "L.strfn.desc_substr": "{t} ဇယားမှ {name} နှင့် {name} ၏ ရှေ့ဆုံးစာလုံး {k} လုံးကို ထုတ်ပါ။",
  "L.strfn.desc_concat": "{t} ဇယားမှ {name} နှင့် {cat} ကို \" / \" (နှစ်ဖက်တွင် space) ဖြင့် ဆက်ထားသော ကော်လံတစ်ခုကို ထုတ်ပါ။",
  "L.dates.title": "ရက်စွဲများ (BETWEEN, strftime, date)",
