  "L.dates.desc_range": "{t} ဇယားမှ {d} သည် {a} မှ {b} အတွင်းရှိသော အတန်းများ၏ {name} နှင့် {d} ကို ထုတ်ပါ။",
  "L.dates.desc_month": "{t} ဇယား၏ {d} ၏ လတစ်ခုစီ ('03' ကဲ့သို့ ဂဏန်းနှစ်လုံး) အတွက် လနှင့် အတန်းအရေအတွက်ကို ထုတ်ပါ။",
