  "L.sub1.point": "( ) အတွင်းရှိ SELECT ကို အခြေအနေတွင် သုံးနိုင်သည်။ ပျမ်းမျှကို အရင်မရှာဘဲ query တစ်ခုတည်းဖြင့် ပျမ်းမျှထက်များသော အတန်းများကို ထုတ်နိုင်သည်။",
  "L.sub1.desc": "{t} ဇယားမှ {c} သည် {c} ၏ ပျမ်းမျှထက် ကြီးသော အတန်းများ၏ {name} နှင့် {c} ကို ထုတ်ပါ။",
  "L.sub1.desc_gt": "{t} ဇယားမှ {c} သည် {c} ၏ ပျမ်းမျှထက် ကြီးသော အတန်းများ၏ {name} နှင့် {c} ကို ထုတ်ပါ။",
  "L.sub1.desc_lt": "{t} ဇယားမှ {c} သည် {c} ၏ ပျမ်းမျှထက် ငယ်သော အတန်းများ၏ {name} နှင့် {c} ကို ထုတ်ပါ။",
  "L.sub1.desc_max": "{t} ဇယားမှ {c} အကြီးဆုံးဖြစ်သော အတန်း၏ {name} နှင့် {c} ကို ထုတ်ပါ။",
  "L.sub1.desc_min": "{t} ဇယားမှ {c} အငယ်ဆုံးဖြစ်သော အတန်း၏ {name} နှင့် {c} ကို ထုတ်ပါ။",
  "L.subin.title": "IN နှင့် subquery",
  "L.subin.point": "WHERE ကော်လံ IN (SELECT …) သည် အခြားဇယားတွင် ပေါ်သောတန်ဖိုးရှိသည့် အတန်းများကိုသာ ထားသည်၊ NOT IN သည် မပေါ်သောအတန်းများကို ထားသည်။ JOIN မသုံးဘဲ ရေးနိုင်သည်။",
  "L.subin.desc": "{R} တွင် {num} သည် {x} နှင့်အထက် ရှိသောအတန်းရှိသူများအတွက် {L} မှ {name} ကို ထုတ်ပါ ({L}.{id} = {R}.{key})။",
  "L.subin.desc_not": "{R} တွင် လုံးဝမပေါ်သူများအတွက် {L} မှ {name} ကို ထုတ်ပါ ({L}.{id} = {R}.{key})။",
  "L.subfrom.title": "FROM အတွင်းရှိ subquery",
