  "pz.p.pz1e.d": "ကဖေး မီနူးဇယား `menu` ရှိသည်။ `category` သည် `'drink'` ဖြစ်ပြီး `price` ယန်း ၄၀၀ နှင့်အောက်ရှိသော မီနူး၏ `name` နှင့် `price` ကို ပြပါ။\n`price` နည်းရာမှ; ဈေးတူလျှင် `id` အစဉ်။",
  "pz.p.pz1e.how": "ဘာပြမလဲ? အမည်နှင့် ဈေး → `SELECT name, price`\nဘယ်ဇယား → `FROM menu`\nအခြေအနေ ၂ ခု: အဖျော်ယမကာ နှင့် ယန်း ၄၀၀ နှင့်အောက် → `WHERE category = 'drink' AND price <= 400` (\"နှင့်အောက်\" တွင် ၄၀၀ ပါ)\nအစဉ်: ဈေးပေါသည်ကို အရင်၊ ထို့နောက် id → `ORDER BY price, id`\nဝှက်ဒေတာတွင် ယန်း ၄၀၀ အတိအကျ အဖျော်ယမကာ ပါသည်။",
