  "tc.send.lessons": "တိုက်ရိုက်အတန်း သင်ခန်းစာ",
  "tc.send.lessonsNote": "အတန်းထဲတွင် တိုက်ရိုက်လုပ်သော သင်ခန်းစာ။ ကျောင်းသားများ၏ အလုပ်တွင် ရွေးထားသည့်အစဉ်အတိုင်း ပေါ်သည်။",
  "tc.send.lessonsSave": "ဤသင်ခန်းစာများ ပို့ရန်",
