  "tc.send.matrixSub": "ပို့နေသည့်အရာများတွင် ကျောင်းသားတစ်ဦးစီ၏ တိုးတက်မှု။ ✓ = ပြီး၊ ဂဏန်း = မည်မျှအထိ။",
  "tc.send.done": "ပြီး",
