  "as.leaveConfirm": "စာမေးပွဲ ဖြေနေဆဲ ဖြစ်သည်။ ဤစာမျက်နှာမှ ထွက်လျှင် စာမေးပွဲ ဤနေရာတွင် ပြီးဆုံးပြီး ထပ်ဖြေ၍ မရပါ။ ထွက်မလား?",
  "tc.send.checkHere": "ဤနေရာတွင် စစ်ဆေးစာမေးပွဲ ဖန်တီးပြီး ချက်ချင်း ပို့နိုင်သည်။ ပါမည့် မေးခွန်းများကို ညာဘက်တွင် ပြသည်။",
  "ck.perLesson": "သင်ခန်းစာ တစ်ခုလျှင်",
