  "ck.calcSome": "သင်ခန်းစာ {l} × {per} = မေးခွန်း {all} → ထိုထဲမှ ကျပန်း {n} ခု။",
  "ck.calcAll": "သင်ခန်းစာ {l} × {per} = မေးခွန်း {n} ခုလုံး။",
